using System.Data;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Storage;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Identity;
using Shop.Modules.Inventory;
using Shop.SharedKernel;
using Xunit;
namespace Shop.SqlTests;
public sealed partial class StockOrderReservationV2SqlTests
{
    private Task<PartialFulfillmentView> PartialView(string owner,string reservation)=>Tx(db=>Reservations(db).ReadRemainingAsync(owner,reservation,default));
    private static PartialDispatchRequest PartialInput(string owner,PartialFulfillmentView view,params PartialDispatchSelection[] lines)=>new(owner,view.ReservationId,Id(),"partial-inventory-qa",Id(),view.Fingerprint,lines);
    private Task<PartialDispatchData> PartialWrite(PartialDispatchRequest input,bool demo=true)=>Tx(db=>Reservations(db,demo).DispatchAsync(input,default));
    private async Task<(Setup Setup,StockOrderReservationDataV2 Hold)> PartialReady(bool tracked=false,int first=2,int second=1,int ordinary=1,bool demo=false)
    {
        var setup=await Prepare(tracked,first,second,ordinary,demo);var hold=await Hold(setup);await Scope(db=>V2(db).AllocateAsync(setup.Request.OwnerId,hold.Id,"partial-inventory-qa",default));return(setup,hold);
    }
    [Fact]public async Task PartialSameSkuDispatchesPreserveSeparateRightsAndDecreaseOnlySelectedCountersExactlyOnce()
    {
        var s=await PartialReady();var owner=s.Setup.Request.OwnerId;var view=await PartialView(owner,s.Hold.Id);var first=view.Lines.First(x=>x.Ordered==2);var request=PartialInput(owner,view,new PartialDispatchSelection(first.LineKey,1,[]));var deadline=s.Hold.ExpiresAt;var originalRights=await Scope(async db=>JsonSerializer.Serialize(new{Items=await db.ReservationItems.AsNoTracking().Where(x=>x.ReservationId==s.Hold.Id).ToArrayAsync(),Lines=await db.ReservationLineEntitlements.AsNoTracking().Where(x=>x.ReservationId==s.Hold.Id).OrderBy(x=>x.LineId).ToArrayAsync(),Transfers=await db.SourcingAllocationTransfers.AsNoTracking().Where(x=>x.ReservationId==s.Hold.Id).OrderBy(x=>x.AllocationId).ToArrayAsync()}));
        var one=await PartialWrite(request);Assert.Equal(1,one.Sequence);Assert.Equal(StockReservationState.Allocated,one.StateAfter);Assert.NotEqual(view.Version,one.ReservationVersionAfter);var stock=await Stock(s.Setup.Variant);Assert.Equal(3,stock.OnHand);Assert.Equal(3,stock.Reserved);view=await PartialView(owner,s.Hold.Id);Assert.Equal(3,view.Lines.Sum(x=>x.Remaining));Assert.Equal(1,view.Lines.Sum(x=>x.Dispatched));var final=await PartialWrite(PartialInput(owner,view,view.Lines.Where(x=>x.Remaining>0).Select(x=>new PartialDispatchSelection(x.LineKey,x.Remaining,[])).ToArray()));Assert.Equal(StockReservationState.Fulfilled,final.StateAfter);Assert.Equal(2,final.Sequence);Assert.Single(final.Lines.Select(x=>x.MovementId).Distinct());stock=await Stock(s.Setup.Variant);Assert.Equal(0,stock.OnHand);Assert.Equal(0,stock.Reserved);Assert.All((await PartialView(owner,s.Hold.Id)).Lines,x=>Assert.Equal(0,x.Remaining));
        clock.Advance(TimeSpan.FromHours(2));var replay=await PartialWrite(request);Assert.True(replay.Replayed);Assert.Equal(JsonSerializer.Serialize(one),JsonSerializer.Serialize(replay with{Replayed=false}));
        await Scope(async db=>{Assert.Equal(deadline,(await db.Reservations.AsNoTracking().SingleAsync(x=>x.Id==s.Hold.Id)).ExpiresAt);Assert.Equal(2,await db.Movements.CountAsync(x=>x.VariantId==s.Setup.Variant&&x.Delta<0));Assert.Single(await db.ReservationEvents.Where(x=>x.ReservationId==s.Hold.Id&&x.State==StockReservationState.Fulfilled).ToArrayAsync());Assert.Equal(originalRights,JsonSerializer.Serialize(new{Items=await db.ReservationItems.AsNoTracking().Where(x=>x.ReservationId==s.Hold.Id).ToArrayAsync(),Lines=await db.ReservationLineEntitlements.AsNoTracking().Where(x=>x.ReservationId==s.Hold.Id).OrderBy(x=>x.LineId).ToArrayAsync(),Transfers=await db.SourcingAllocationTransfers.AsNoTracking().Where(x=>x.ReservationId==s.Hold.Id).OrderBy(x=>x.AllocationId).ToArrayAsync()}));return true;});
    }
    [Fact]public async Task TrackedPartialDispatchClosesOnlySelectedSourcingClaimsAndBlocksLegacyReassignmentReleaseAndFullFulfill()
    {
        var s=await PartialReady(true);var owner=s.Setup.Request.OwnerId;
        var picks=await Scope(async db=>{var units=await db.SerialUnits.AsNoTracking().Where(x=>x.VariantId==s.Setup.Variant).OrderBy(x=>x.Id).ToArrayAsync();var claims=await db.SerialUnitClaims.AsNoTracking().Where(x=>x.ReservationId==s.Hold.Id).ToArrayAsync();var ordinary=s.Setup.Request.Lines.Single(x=>x.AllocationId is null);return units.Select(x=>new StockOrderSerialPickV2(claims.SingleOrDefault(c=>c.UnitId==x.Id)?.OrderLineId??ordinary.LineId,x.Id,Convert.ToBase64String(x.Version))).ToArray();});var assignment=Id();await Assign(s.Setup,s.Hold,picks,assignment);var view=await PartialView(owner,s.Hold.Id);Assert.Equal(4,view.RemainingUnits.Length);var claimed=picks.First(x=>s.Setup.Request.Lines.Any(l=>l.LineId==x.LineId&&l.AllocationId is not null));await PartialWrite(PartialInput(owner,view,new PartialDispatchSelection(claimed.LineId,1,[claimed.UnitId])));
        view=await PartialView(owner,s.Hold.Id);Assert.Equal(3,view.RemainingUnits.Length);await Scope(async db=>{Assert.Equal(1,await db.SerialUnitClaims.CountAsync(x=>x.ReservationId==s.Hold.Id&&x.State=="Fulfilled"));Assert.Equal(2,await db.SerialUnitClaims.CountAsync(x=>x.ReservationId==s.Hold.Id&&x.State=="Assigned"));Assert.Equal(1,await db.SerialUnits.CountAsync(x=>x.ReservationId==s.Hold.Id&&x.State=="delivered"));return true;});
        Assert.Equal("reservation_partial_fulfillment_conflict",(await Assert.ThrowsAsync<BusinessException>(()=>Scope(db=>V2(db).ReleaseAsync(owner,s.Hold.Id,"partial-inventory-qa",default)))).Code);Assert.Equal("reservation_partial_fulfillment_conflict",(await Assert.ThrowsAsync<BusinessException>(()=>Scope(db=>V2(db).FulfillAsync(owner,s.Hold.Id,"partial-inventory-qa",default)))).Code);await Assign(s.Setup,s.Hold,picks,assignment);Assert.Equal("reservation_partial_fulfillment_conflict",(await Assert.ThrowsAsync<BusinessException>(()=>Assign(s.Setup,s.Hold,picks))).Code);
        var final=await PartialWrite(PartialInput(owner,view,view.Lines.Where(x=>x.Remaining>0).Select(l=>new PartialDispatchSelection(l.LineKey,l.Remaining,view.RemainingUnits.Where(u=>u.LineKey==l.LineKey).Select(u=>u.Id).ToArray())).ToArray()));Assert.Equal(StockReservationState.Fulfilled,final.StateAfter);await Scope(async db=>{Assert.Equal(3,await db.SerialUnitClaims.CountAsync(x=>x.ReservationId==s.Hold.Id&&x.State=="Fulfilled"));Assert.Equal(4,await db.SerialUnits.CountAsync(x=>x.ReservationId==s.Hold.Id&&x.State=="delivered"));return true;});
    }
    [Fact]public async Task SameCommandConcurrentReplayHasOneDispatchAndChangedBodyCannotReuseItsReceipt()
    {
        var s=await PartialReady(false,2,0,0);var owner=s.Setup.Request.OwnerId;var view=await PartialView(owner,s.Hold.Id);var input=PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[]));var results=await Task.WhenAll(PartialWrite(input),PartialWrite(input));Assert.Single(results,x=>!x.Replayed);Assert.Single(results,x=>x.Replayed);Assert.Equal(1,(await Stock(s.Setup.Variant)).OnHand);Assert.Equal("idempotency_conflict",(await Assert.ThrowsAsync<BusinessException>(()=>PartialWrite(input with{Lines=[new(view.Lines[0].LineKey,2,[])]}))).Code);await Scope(async db=>{Assert.Single(await db.PartialDispatches.Where(x=>x.ReservationId==s.Hold.Id).ToArrayAsync());return true;});
    }
    [Fact]public async Task CompetingParcelsCannotBothSpendTheSameRemainingUnit()
    {
        var s=await PartialReady(false,1,0,0);var owner=s.Setup.Request.OwnerId;var view=await PartialView(owner,s.Hold.Id);async Task<bool> Attempt(){try{await PartialWrite(PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[])));return true;}catch(BusinessException e)when(e.Code.Contains("conflict",StringComparison.Ordinal)){return false;}}var outcomes=await Task.WhenAll(Attempt(),Attempt());Assert.Single(outcomes,x=>x);Assert.Equal(0,(await Stock(s.Setup.Variant)).OnHand);await Scope(async db=>{Assert.Single(await db.PartialDispatches.Where(x=>x.ReservationId==s.Hold.Id).ToArrayAsync());return true;});
    }
    [Fact]public async Task CallerAuditFailureRollsBackStockLedgerReservationVersionAndDispatchRows()
    {
        var s=await PartialReady();var owner=s.Setup.Request.OwnerId;var view=await PartialView(owner,s.Hold.Id);var input=PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[]));var before=await Snapshot(s.Setup.Variant);
        await Assert.ThrowsAsync<DbUpdateException>(async()=>{await using var scope=fixture.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<InventoryDbContext>();var identity=scope.ServiceProvider.GetRequiredService<IdentityDbContext>();await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);identity.Database.SetDbConnection(db.Database.GetDbConnection(),false);await identity.Database.UseTransactionAsync(tx.GetDbTransaction());try{await Reservations(db).DispatchAsync(input,default);identity.Audit.Add(new AuditEvent{ActorId=new string('x',10000),Action="SYNTHETIC_PARTIAL_AUDIT_FAILURE",Resource="/qa",TraceId="qa"});await identity.SaveChangesAsync();}finally{await identity.Database.UseTransactionAsync(null);}});
        Assert.Equal(before,await Snapshot(s.Setup.Variant));Assert.Equal(view.Fingerprint,(await PartialView(owner,s.Hold.Id)).Fingerprint);await Scope(async db=>{Assert.False(await db.PartialDispatches.AnyAsync(x=>x.ReservationId==s.Hold.Id));return true;});Assert.False((await PartialWrite(input)).Replayed);
    }
    [Fact]public async Task LegacyOrdinaryReservationSupportsPartialDispatchAndRetainsHistoricalModeAfterCompleteSkuModeChange()
    {
        var s=await Prepare(false,0,0,2);var owner=s.Request.OwnerId;var hold=await Scope(db=>Reservations(db).HoldAsync(new(owner,s.Request.OrderId,Id(),[new(s.Variant,2)],TimeSpan.FromMinutes(10)),default));await Scope(db=>Reservations(db).AllocateAsync(owner,hold.Id,"partial-inventory-qa",default));var view=await PartialView(owner,hold.Id);Assert.Equal(1,view.ReservationContract);var request=PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[]));await PartialWrite(request);Assert.Equal("reservation_partial_fulfillment_conflict",(await Assert.ThrowsAsync<BusinessException>(()=>Scope(db=>Reservations(db).ReleaseAsync(owner,hold.Id,"partial-inventory-qa",default)))).Code);view=await PartialView(owner,hold.Id);await PartialWrite(PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[])));var stock=await Stock(s.Variant);await Tx(db=>new SerialInventoryService(db,Reservations(db),clock).ConfigureAsync(s.Variant,false,new("serial",Convert.ToBase64String(stock.Version),Id()),"partial-inventory-qa",default));Assert.Equal("none",(await PartialView(owner,hold.Id)).Lines[0].TrackingMode);Assert.True((await PartialWrite(request)).Replayed);
    }
    [Fact]public async Task ProductionCannotReadOrReplayDemoPartialDispatchHistory()
    {
        var s=await PartialReady(false,2,0,0,true);var view=await PartialView(s.Setup.Request.OwnerId,s.Hold.Id);var input=PartialInput(s.Setup.Request.OwnerId,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[]));Assert.True((await PartialWrite(input)).ContainsDemo);Assert.Equal("not_found",(await Assert.ThrowsAsync<BusinessException>(()=>Tx(db=>Reservations(db,false).ReadRemainingAsync(s.Setup.Request.OwnerId,s.Hold.Id,default)))).Code);Assert.Equal("not_found",(await Assert.ThrowsAsync<BusinessException>(()=>PartialWrite(input,false))).Code);
    }
    [Fact]public async Task LegacyImeiUnitsRemainPrivateHistoricalFactsAndCannotBeReassignedAfterFirstDispatch()
    {
        var variant="partial-imei-"+Id();var owner="owner-"+Id();await Scope(async db=>{db.Stock.Add(new(){VariantId=variant});await db.SaveChangesAsync();return true;});var stock=await Stock(variant);await Tx(db=>new SerialInventoryService(db,Reservations(db),clock).ConfigureAsync(variant,false,new("imei",Convert.ToBase64String(stock.Version),Id()),"partial-inventory-qa",default));stock=await Stock(variant);var receipt=await Tx(db=>new SerialInventoryService(db,Reservations(db),clock).ReceiveAsync(variant,false,new([new(null,"490154203237518"),new(null,"356938035643809")],"SYNTHETIC IMEI partial dispatch fixture",Convert.ToBase64String(stock.Version),Id()),"partial-inventory-qa",default));
        var hold=await Scope(db=>Reservations(db).HoldAsync(new(owner,Id(),Id(),[new(variant,2)],TimeSpan.FromMinutes(10)),default));await Scope(db=>Reservations(db).AllocateAsync(owner,hold.Id,"partial-inventory-qa",default));var assignment=new StockSerialAssignment(owner,hold.Id,"partial-inventory-qa",Id(),receipt.Units.Select(u=>new StockSerialPick(u.Id,u.Version)).ToArray());await Scope(async db=>{await new SerialInventoryService(db,Reservations(db),clock).AssignAsync(assignment,default);return true;});
        var view=await PartialView(owner,hold.Id);var input=PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[view.RemainingUnits[0].Id]));var one=await PartialWrite(input);Assert.Null(one.Units[0].Serial);Assert.Contains(one.Units[0].Imei1,new[]{"490154203237518","356938035643809"});Assert.Equal("imei",one.Lines[0].TrackingMode);
        await Scope(async db=>{await new SerialInventoryService(db,Reservations(db),clock).AssignAsync(assignment,default);return true;});Assert.Equal("reservation_partial_fulfillment_conflict",(await Assert.ThrowsAsync<BusinessException>(()=>Scope(async db=>{await new SerialInventoryService(db,Reservations(db),clock).AssignAsync(assignment with{RequestId=Id()},default);return true;}))).Code);
        view=await PartialView(owner,hold.Id);await PartialWrite(PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[view.RemainingUnits[0].Id])));Assert.Equal(JsonSerializer.Serialize(one),JsonSerializer.Serialize((await PartialWrite(input))with{Replayed=false}));Assert.Equal(0,(await Stock(variant)).OnHand);
    }
    [Fact]public async Task FinalDispatchSlotMustCloseEveryRemainingQuantityInsteadOfStrandingAnAllocatedOrder()
    {
        var s=await Prepare(false,0,0,65);var owner=s.Request.OwnerId;var hold=await Scope(db=>Reservations(db).HoldAsync(new(owner,s.Request.OrderId,Id(),[new(s.Variant,65)],TimeSpan.FromMinutes(10)),default));await Scope(db=>Reservations(db).AllocateAsync(owner,hold.Id,"partial-inventory-qa",default));
        for(var n=0;n<63;n++){var page=await PartialView(owner,hold.Id);var written=await PartialWrite(PartialInput(owner,page,new PartialDispatchSelection(page.Lines[0].LineKey,1,[])));Assert.Equal(n+1,written.Sequence);}
        var view=await PartialView(owner,hold.Id);Assert.Equal(2,view.Lines[0].Remaining);Assert.Equal("partial_fulfillment_capacity_unavailable",(await Assert.ThrowsAsync<BusinessException>(()=>PartialWrite(PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[]))))).Code);var final=await PartialWrite(PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,2,[])));Assert.Equal(64,final.Sequence);Assert.Equal(StockReservationState.Fulfilled,final.StateAfter);Assert.Equal(0,(await Stock(s.Variant)).Reserved);
    }
    [Fact]public async Task DispatchHistoryRejectsEfMutationCorruptionAndDestructiveMigrationDown()
    {
        var s=await PartialReady();var view=await PartialView(s.Setup.Request.OwnerId,s.Hold.Id);var input=PartialInput(s.Setup.Request.OwnerId,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[]));await PartialWrite(input);string original="";
        await Scope(async db=>{var row=await db.PartialDispatches.SingleAsync(x=>x.Id==input.ParcelId);original=row.ResponseHash;row.ResponseHash=new('B',64);await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());return true;});
        await Scope(async db=>{await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [inventory].[PartialDispatches] SET [ResponseHash]={new string('B',64)} WHERE [Id]={input.ParcelId}");return true;});
        try{Assert.Equal("partial_fulfillment_unavailable",(await Assert.ThrowsAsync<BusinessException>(()=>PartialWrite(input))).Code);}finally{await Scope(async db=>{await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [inventory].[PartialDispatches] SET [ResponseHash]={original} WHERE [Id]={input.ParcelId}");return true;});}
        await Scope(async db=>{var migrations=(await db.Database.GetAppliedMigrationsAsync()).ToArray();Assert.EndsWith("_PartialInventoryDispatches",migrations[^1]);var error=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<Microsoft.EntityFrameworkCore.Migrations.IMigrator>().MigrateAsync(migrations[^2]));Assert.Equal(51000,error.Number);Assert.Single(await db.PartialDispatches.Where(x=>x.Id==input.ParcelId).ToArrayAsync());return true;});Assert.True((await PartialWrite(input)).Replayed);
    }
    [Fact]public async Task ReleaseAndPartialDispatchRaceCannotBothConsumeTheSameReservation()
    {
        var s=await PartialReady(false,2,0,0);var owner=s.Setup.Request.OwnerId;var view=await PartialView(owner,s.Hold.Id);async Task<bool> Dispatch(){try{await PartialWrite(PartialInput(owner,view,new PartialDispatchSelection(view.Lines[0].LineKey,1,[])));return true;}catch(BusinessException e)when(e.Code.Contains("conflict",StringComparison.Ordinal)){return false;}}async Task<bool> Release(){try{await Scope(db=>V2(db).ReleaseAsync(owner,s.Hold.Id,"partial-inventory-qa",default));return true;}catch(BusinessException e)when(e.Code.Contains("conflict",StringComparison.Ordinal)){return false;}}var results=await Task.WhenAll(Dispatch(),Release());Assert.Single(results,x=>x);var stock=await Stock(s.Setup.Variant);Assert.True(stock.OnHand==1&&stock.Reserved==1||stock.OnHand==2&&stock.Reserved==0);
    }
}
